/bin/bash -lc "mkdir -p /workspace/galaxy_outputs /workspace/codex_output && python - <<'PY'
import os, csv
from bioblend.galaxy import GalaxyInstance
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
gi=GalaxyInstance(url='https://usegalaxy.org', key=key)
ids={
 'iron':'f9cad7b01a472135a1d341edf9355eda',
 'innate':'f9cad7b01a47213526bf7faecf0e1e83',
}
for label,did in ids.items():
    gi.datasets.download_dataset(did, file_path=f'/workspace/galaxy_outputs/{label}_kegg.tsv', use_default_filename=False)
sets={}
rows={}
for label in ids:
    with open(f'/workspace/galaxy_outputs/{label}_kegg.tsv', newline='') as f:
        data=list(csv.DictReader(f, delimiter='\\t'))
    rows[label]=data
    sets[label]={r['pathway_id'] for r in data if float(r['adjusted_p_value']) < 0.05}
only=sorted(sets['iron']-sets['innate'])
print('iron_significant',len(sets['iron']),sorted(sets['iron']))
print('innate_significant',len(sets['innate']),sorted(sets['innate']))
print('iron_only',len(only),only)
for r in rows['iron']:
    if r['pathway_id'] in only:
        print(r['pathway_id'],r['pathway_name'],r['adjusted_p_value'])
PY"
